6	import { runPlanReview } from "@symbiot/agent-runtime";
7	import { emitBlockDecision } from "@symbiot/agent-runtime/decision";
8	import { isMissing } from "@symbiot/agent-runtime/managed-file";
9	import { sha256 } from "@symbiot/agent-runtime/marker-store";
10	// Bun's compile mode embeds this file into the binary; the import resolves to
11	// a `$bunfs/…` virtual path at runtime that fs APIs read transparently.
12	import viewerHtmlGz from "@symbiot/viewer/dist/embed/index.html.gz" with { type: "file" };
13	
14	/**
15	 * JSON payload Claude Code writes to the hook's stdin. The same shape covers
16	 * both `PreToolUse` (drives the viewer) and `PermissionRequest` (defensive
17	 * short-circuit for anthropics/claude-code#50660). Only `ExitPlanMode`
18	 * invocations carry the plan in `tool_input.plan`; everything else is ignored.
19	 *
20	 * @example
21	 *   { "hook_event_name": "PreToolUse",
22	 *     "tool_name": "ExitPlanMode",
23	 *     "tool_input": { "plan": "# Plan\n\n..." } }
24	 */
25	interface HookInput {
26	  hook_event_name?: string;
27	  tool_name?: string;
28	  tool_input?: { plan?: string };
29	}
30	
31	/** On-disk shape of the approve marker the PreToolUse run leaves for the PermissionRequest run. */
32	export interface ApproveMarker {
33	  planHash: string;
34	  approvedAt: number;
35	}
36	
37	/** Anything older than this gates the PermissionRequest path back to "ask" — see runHook JSDoc. */
38	export const approveMarkerTtlMs = 60_000;
39	
40	export const markerPath = (): string =>
41	  join(homedir(), ".symbiot", "hook-state", "last-approve.json");
42	
43	const eventLogPath = (): string => join(homedir(), ".symbiot", "hook-state", "events.log");
44	
45	/**
46	 * Append a single JSON line per hook invocation for post-hoc debugging.
47	 * The log is observability, never load-bearing — failures must not
48	 * propagate (a throw would abort Claude Code's plan dispatch). Missing-
49	 * path errors stay silent (first-invocation case); other failures surface
50	 * a single-line warning on stderr so corruption / permission issues do
51	 * not vanish.
52	 */
53	const logEvent = async (entry: Record<string, unknown>): Promise<void> => {
54	  try {
55	    const target = eventLogPath();
56	    await mkdir(dirname(target), { recursive: true });
57	    await appendFile(target, `${JSON.stringify({ at: Date.now(), ...entry })}\n`, "utf8");
58	  } catch (error) {
59	    if (isMissing(error)) return;
60	    const code = (error as NodeJS.ErrnoException).code ?? "unknown";
61	    process.stderr.write(`symbiot: events.log write failed (${code})\n`);
62	  }
63	};
64	
65	/** SHA-256 fingerprint of a plan; aliases the shared {@link sha256} so the marker hash is computed identically across hooks. */
66	export const hashPlan = sha256;
67	
68	const readHookInput = async (): Promise<HookInput> => {
69	  const chunks: Uint8Array[] = [];
70	  for await (const chunk of process.stdin) chunks.push(chunk as Uint8Array);
71	  if (chunks.length === 0) return {};
72	  return JSON.parse(Buffer.concat(chunks).toString("utf8")) as HookInput;
73	};
74	
75	const planFrom = (input: HookInput): string | null => {
76	  if (input.tool_name !== "ExitPlanMode") return null;
77	  return input.tool_input?.plan ?? null;
78	};
79	
80	export const writeApproveMarker = async (planHash: string): Promise<void> => {
81	  const target = markerPath();
82	  await mkdir(dirname(target), { recursive: true });
83	  const payload: ApproveMarker = { planHash, approvedAt: Date.now() };
84	  const tmp = `${target}.${randomUUID()}.tmp`;
85	  await writeFile(tmp, JSON.stringify(payload), "utf8");
86	  await rename(tmp, target);
87	};
88	
89	const isPlanHash = (value: unknown): value is string =>
90	  typeof value === "string" && /^[a-f0-9]{64}$/.test(value);
91	
92	const isApprovedAt = (value: unknown): value is number =>
93	  typeof value === "number" && Number.isFinite(value);
94	
95	const isApproveMarker = (value: unknown): value is ApproveMarker => {
96	  if (typeof value !== "object" || value === null) return false;
97	  const { planHash, approvedAt } = value as Record<string, unknown>;
98	  return isPlanHash(planHash) && isApprovedAt(approvedAt);
99	};
100	
101	/**
102	 * Read the most recent approve marker. Returns `null` on any failure
103	 * (missing file, malformed JSON, schema mismatch) so callers can fall back to
104	 * the no-op `permissionDecision: "ask"` path without partial signals.
105	 * Missing-path errors stay silent (no marker yet); other errors emit a
106	 * one-line stderr warning so corruption / permission issues are visible.
107	 */
108	export const readApproveMarker = async (): Promise<ApproveMarker | null> => {
109	  try {
110	    const raw = await readFile(markerPath(), "utf8");
111	    const parsed: unknown = JSON.parse(raw);
112	    return isApproveMarker(parsed) ? parsed : null;
113	  } catch (error) {
114	    if (!isMissing(error)) {
115	      const code = (error as NodeJS.ErrnoException).code ?? "parse";
116	      process.stderr.write(`symbiot: marker read failed (${code})\n`);
117	    }
118	    return null;
119	  }
120	};
121	
122	export const isFreshFor = (marker: ApproveMarker, planHash: string, now: number): boolean =>
123	  marker.planHash === planHash && now - marker.approvedAt < approveMarkerTtlMs;
124	
125	// TODO(symbiot#1, upstream anthropics/claude-code#50660): permissionDecision
126	// is currently silently ignored for ExitPlanMode in Claude Code, so this
127	// PreToolUse payload is a no-op at runtime until upstream ships the fix.
128	// The PermissionRequest hook below uses the nested decision.behavior
129	// schema (also Anthropic-documented) which IS honored for ExitPlanMode.
130	const emitApproveDecision = (): void => {
131	  const payload = {
132	    hookSpecificOutput: {
133	      hookEventName: "PreToolUse",
134	      permissionDecision: "allow",
135	      permissionDecisionReason: "Reviewer approved plan in symbiot.",
136	    },
137	  };
138	  process.stdout.write(JSON.stringify(payload));
139	};
140	
141	/** Shape of the `PermissionRequest` allow payload emitted on approve. */
142	interface PermissionRequestAllowPayload {
143	  hookSpecificOutput: {
144	    hookEventName: "PermissionRequest";
145	    decision: {
146	      behavior: "allow";
147	      updatedPermissions: Array<{ type: "setMode"; mode: "auto"; destination: "session" }>;
148	    };
149	  };
150	}
151	
152	/**
153	 * The nested `{decision: {behavior: "allow"}}` shape Claude Code honors for the
154	 * `PermissionRequest(ExitPlanMode)` matcher — distinct from the PreToolUse-only
155	 * `permissionDecision` field. The `updatedPermissions` `setMode` entry
156	 * reproduces the choice the native "Accept this plan?" prompt offers ("start in
157	 * auto mode"): because the viewer replaces that prompt, the post-plan permission
158	 * mode must be carried here, or Claude Code falls back to its post-approval
159	 * `acceptEdits` default. Exported so the payload shape can be unit-asserted.
160	 */
161	export const permissionRequestAllowPayload = (): PermissionRequestAllowPayload => ({
162	  hookSpecificOutput: {
163	    hookEventName: "PermissionRequest",
164	    decision: {
165	      behavior: "allow",
166	      updatedPermissions: [{ type: "setMode", mode: "auto", destination: "session" }],
167	    },
168	  },
169	});
170	
171	const emitPermissionRequestAllow = (): void => {
172	  process.stdout.write(JSON.stringify(permissionRequestAllowPayload()));
173	};
174	
175	const runPreToolUse = (plan: string): Promise<number> => {
176	  const planHash = hashPlan(plan);
177	  return runPlanReview({
178	    plan,
179	    serverOptions: { indexHtmlGz: viewerHtmlGz, agentId: "claude-code" },
180	    onStart: (url) => process.stderr.write(`symbiot: review plan at ${url}\n`),
181	    onResolved: async (decision) => {
182	      if (decision.kind === "approve") {
183	        await writeApproveMarker(planHash);
184	        emitApproveDecision();
185	        await logEvent({ event: "PreToolUse", planHash, emitted: "allow" });
186	        return 0;
187	      }
188	      await emitBlockDecision(decision.feedback);
189	      await logEvent({ event: "PreToolUse", planHash, emitted: "block" });
190	      return 0;
191	    },
192	  });
193	};
194	
195	const runPermissionRequest = async (plan: string): Promise<number> => {
196	  const planHash = hashPlan(plan);
197	  const marker = await readApproveMarker();
198	  const fresh = marker !== null && isFreshFor(marker, planHash, Date.now());
199	  if (fresh) {
200	    emitPermissionRequestAllow();
201	    await logEvent({ event: "PermissionRequest", planHash, marker, emitted: "allow" });
202	    return 0;
203	  }
204	  // No fresh marker → write nothing. Claude Code interprets empty hook
205	  // output as "no decision" and falls through to its native prompt,
206	  // matching today's UX without a hook at all (graceful degradation).
207	  await logEvent({ event: "PermissionRequest", planHash, marker, emitted: "passthrough" });
208	  return 0;
209	};
210	
211	/**
212	 * Claude Code hook entry point for the `ExitPlanMode` tool. Handles two
213	 * events that the installer registers under the same matcher:
214	 *
215	 *   - `PreToolUse` — spawn the viewer, block until the reviewer decides.
216	 *     Approve → write a short-lived marker keyed by SHA-256 of the plan, then
217	 *     emit the documented `permissionDecision: "allow"` payload (no-op against
218	 *     today's #50660 bug, kept future-proof). Request changes → emit
219	 *     `{decision: "block", reason}` so Claude sees the feedback and revises;
220	 *     this path uses the older top-level `decision` field and is unaffected
221	 *     by the upstream bug. A `block` short-circuits tool dispatch, so
222	 *     `PermissionRequest` does not fire on the deny path.
223	 *   - `PermissionRequest` — suppresses Claude Code's native "Accept this
224	 *     plan?" prompt by emitting the nested `decision.behavior: "allow"`
225	 *     schema (NOT `permissionDecision` — that field is the PreToolUse-only
226	 *     schema and is ignored here). Reads the marker left by the PreToolUse
227	 *     run; if the plan hash matches and the marker is younger than 60 s,
228	 *     emits the allow payload, whose `updatedPermissions` `setMode` entry
229	 *     switches the session to `auto` mode (the native prompt's "start in auto
230	 *     mode" choice) instead of Claude Code's post-approval `acceptEdits`
231	 *     default. Otherwise writes nothing so Claude Code falls through to its
232	 *     native prompt — graceful degradation.
233	 */
234	export const runHook = async (): Promise<number> => {
235	  const input = await readHookInput();
236	  await logEvent({
237	    event: "invoked",
238	    hook_event_name: input.hook_event_name,
239	    tool_name: input.tool_name,
240	    hasPlan: typeof input.tool_input?.plan === "string",
241	  });
242	  const plan = planFrom(input);
243	  if (plan === null) return 0;
244	  if (input.hook_event_name === "PermissionRequest") {
245	    return runPermissionRequest(plan);
246	  }
247	  return runPreToolUse(plan);
248	};
